mapper.select:
SELECT a.REGIST_SEQNO registSeqno, a.SEND_STATUS sendStatus, a.SUBMIT_FEEDBACK_MSG submitFeedbackMsg, a.SUBMIT_FEEDBACK_STATUS submitFeedbackStatus, a.SUBMIT_TIME submitTime, a.CHB_SUBMIT_DEADLINE chbSubmitDeadline, a.SUBMIT_DEADLINE submitDeadline, a.STATUS status, a.AGENT_INSTITUTION_CODE agentInstitutionCode, a.AGENT_INSTITUTION_NAME agentInstitutionName, a.ISSUE_PARTY_ID issuePartyId, a.SUMIT_SEQ sumitSeq, a.DATA_DATE dataDate, a.ENCLOSURE_NUM enclosureNum, a.FILE_NO fileNo, a.ENCLOSURE_ADDRESS enclosureAddress, a.ENCLOSURE_CHANGE_FLAG enclosureChangeFlag, a.REMARK remark, a.UPDATE_TIME FROM CHB_AGENT_INSTITUTION_SUB a where 1=1
and a.AGENT_INSTITUTION_CODE = #{agentInstitutionCode}
and a.SUBMIT_FEEDBACK_STATUS = #{submitFeedbackStatus}
and a.SEND_STATUS = #{sendStatus}
#{status}
and a.CHB_SUBMIT_DEADLINE between to_date(#{searchSubmitDeadlineStart,jdbcType=VARCHAR},'yyyy-mm-dd') and to_date(#{searchSubmitDeadlineEnd,jdbcType=VARCHAR},'yyyy-mm-dd')
and to_char(a.DATA_DATE,'yyyy-MM-dd') >= #{searchDataDateStart,jdbcType=VARCHAR}
and to_char(a.DATA_DATE,'yyyy-MM-dd') <= #{searchDataDateEnd,jdbcType=VARCHAR}
and to_char(a.SUBMIT_TIME,'yyyy-MM-dd') >= #{searchSubmitTimeStart,jdbcType=VARCHAR}
and to_char(a.SUBMIT_TIME,'yyyy-MM-dd') <= #{searchSubmitTimeEnd,jdbcType=VARCHAR}
ORDER BY a.UPDATE_TIME DESC

select * from ( SELECT REGIST_SEQNO registSeqno, SEND_STATUS sendStatus, SUBMIT_FEEDBACK_MSG submitFeedbackMsg, SUBMIT_FEEDBACK_STATUS submitFeedbackStatus, SUBMIT_TIME submitTime, CHB_SUBMIT_DEADLINE chbSubmitDeadline, SUBMIT_DEADLINE submitDeadline, STATUS status, AGENT_INSTITUTION_CODE agentInstitutionCode, AGENT_INSTITUTION_NAME agentInstitutionName, ISSUE_PARTY_ID issuePartyId, SUMIT_SEQ sumitSeq, DATA_DATE dataDate, FILE_NO fileNo, ENCLOSURE_NUM enclosureNum, ENCLOSURE_ADDRESS enclosureAddress, ENCLOSURE_CHANGE_FLAG enclosureChangeFlag, REMARK remark, UPDATE_TIME FROM CHB_AGENT_INSTITUTION_SUB
#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
#{submitFeedbackStatus,jdbcType=VARCHAR}
and SUBMIT_DEADLINE between to_date(#{searchSubmitDeadlineStart,jdbcType=VARCHAR},'yyyy-mm-dd') and to_date(#{searchSubmitDeadlineEnd,jdbcType=VARCHAR},'yyyy-mm-dd')
and to_char(DATA_DATE,'yyyy-MM-dd') >= #{searchDataDateStart,jdbcType=VARCHAR}
and to_char(DATA_DATE,'yyyy-MM-dd') <= #{searchDataDateEnd,jdbcType=VARCHAR}
and to_char(SUBMIT_TIME,'yyyy-MM-dd') >= #{searchSubmitTimeStart,jdbcType=VARCHAR}
and to_char(SUBMIT_TIME,'yyyy-MM-dd') <= #{searchSubmitTimeEnd,jdbcType=VARCHAR}
) ORDER BY dataDate

mapper.update:
update CHB_AGENT_INSTITUTION_SUB
SEND_STATUS = '01', SUBMIT_TIME = null, SUBMIT_FEEDBACK_STATUS = null
trim(REGIST_SEQNO) = #{dto.registSeqno}

mapper.insert:
