and a.AGENT_INSTITUTION_CODE = #{agentInstitutionCode}
and a.SUBMIT_FEEDBACK_STATUS = #{submitFeedbackStatus}
and a.SEND_STATUS = #{sendStatus}
#{status}
and a.SUBMIT_DEADLINE between to_date(#{searchSubmitDeadlineStart,jdbcType=VARCHAR},'yyyy-mm-dd') and to_date(#{searchSubmitDeadlineEnd,jdbcType=VARCHAR},'yyyy-mm-dd')
and to_char(a.DATA_DATE,'yyyy-MM-dd') >= #{searchDataDateStart,jdbcType=VARCHAR}
and to_char(a.DATA_DATE,'yyyy-MM-dd') <= #{searchDataDateEnd,jdbcType=VARCHAR}
and to_char(a.SUBMIT_TIME,'yyyy-MM-dd') >= #{searchSubmitTimeStart,jdbcType=VARCHAR}
